/* =====================================================================================

  ---TOP_RESET_CTL (0x81020000 + 0x0)---

    WM_WDT_RESET_EN[0]           - (RW) MCU WMWDT reset enable
    WA_WDT_RESET_EN[1]           - (RW) MCU WA WDT reset enable
    WFSYS_ON_TOP_WDT_RESET_EN[2] - (RW) WFSYS ON TOP WDT reset enable
                                     Note that this 1-bit CR do not be reset by WDT reset, it is reset by power-on reset only
                                     0: disable WFSYS ON TOP WDT reset "WFSYS"
                                     1: enable WFSYS ON TOP WDT reset "WFSYS"
    WFSYS_WDT_MASK_OSC_FOR_MEM_PON_B_SEL[3] - (RW) don't touch if need
    RESERVED4[31..4]             - (RO) Reserved bits

 =====================================================================================*/
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_WDT_MASK_OSC_FOR_MEM_PON_B_SEL_ADDR WF_TOP_RGU_ON_TOP_RESET_CTL_ADDR
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_WDT_MASK_OSC_FOR_MEM_PON_B_SEL_MASK 0x00000008                // WFSYS_WDT_MASK_OSC_FOR_MEM_PON_B_SEL[3]
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_WDT_MASK_OSC_FOR_MEM_PON_B_SEL_SHFT 3
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_ON_TOP_WDT_RESET_EN_ADDR WF_TOP_RGU_ON_TOP_RESET_CTL_ADDR
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_ON_TOP_WDT_RESET_EN_MASK 0x00000004                // WFSYS_ON_TOP_WDT_RESET_EN[2]
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WFSYS_ON_TOP_WDT_RESET_EN_SHFT 2
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WA_WDT_RESET_EN_ADDR       WF_TOP_RGU_ON_TOP_RESET_CTL_ADDR
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WA_WDT_RESET_EN_MASK       0x00000002                // WA_WDT_RESET_EN[1]
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WA_WDT_RESET_EN_SHFT       1
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WM_WDT_RESET_EN_ADDR       WF_TOP_RGU_ON_TOP_RESET_CTL_ADDR
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WM_WDT_RESET_EN_MASK       0x00000001                // WM_WDT_RESET_EN[0]
#define WF_TOP_RGU_ON_TOP_RESET_CTL_WM_WDT_RESET_EN_SHFT       0

/* =====================================================================================

  ---LMACPHY_PWR_CTL (0x81020000 + 0x4)---

    BN0_WF_PWR_RDY_SEL[0]        - (RW) BN0 WF power ready indication selection (BN0 WF means BN0 LMAC and BN0 PHY)
                                     0: CR control
                                     1: H/W signal to present power ready indication
    BN0_WF_PWR_RDY[1]            - (RW) when BN0 WF power ready indication selection = 0 (BN0 WF means BN0 LMAC and BN0 PHY)
                                     0: indicate that BN0 WF power is not ready
                                     1: indicate that BN0 WF power is ready
    BN1_WF_PWR_RDY_SEL[2]        - (RW) BN1 WF power ready indication selection (BN1 WF means BN1 LMAC and BN1 PHY)
                                     0: CR control
                                     1: H/W signal to present power ready indication
    BN1_WF_PWR_RDY[3]            - (RW) when BN1 WF power ready indication selection = 0 (BN1 WF means BN1 LMAC and BN1 PHY)
                                     0: indicate that BN1 WF power is not ready
                                     1: indicate that BN1 WF power is ready
    BNX_WF_PWR_RDY_SEL[4]        - (RW) BNX WF power ready indication selection (BNX means all bands LMAC and PHY)
                                     0: CR control
                                     1: H/W signal to present power ready indication
    BNX_WF_PWR_RDY[5]            - (RW) when BNX WF power ready indication selection = 0 (BNX means all bands LMAC and PHY)
                                     0: indicate that BNX WF power is not ready
                                     1: indicate that BNX WF power is ready
    RESERVED6[6]                 - (RO) Reserved bits
    WF_PWR_ON_SELECT[7]          - (RW) LMAC/PHY 1-to-1 or 1-n selection
                                     0: 1-to-1  <-  BN0 LMAC, BN1 LMAC, BN0 PHY and BN1 PHY is controlled by itself
                                     1: 1-to-n  <-  BN0 LMAC, BN1 LMAC, BN0 PHY and BN1 PHY is controlled by BN0 LMAC
    WF_PHY_BAND_CONFIG[9..8]     - (RW) PHY band configuration  (this setting must be programmed at initial stage, it can not run-time change)
                                     0: X BN1, X BN0
                                     1: X BN1, O BN0
                                     2: O BN1, X BN0
                                     3: O BN1, O BN0
    WF_LMAC_BAND_CONFIG[11..10]  - (RW) LMAC band configuration (this setting must be programmed at initial stage, it can not run-time change)
                                     0: X BN1, X BN0
                                     1: X BN1, O BN0
                                     2: O BN1, X BN0
                                     3: O BN1, O BN0
    RESERVED12[15..12]           - (RO) Reserved bits
    BN0_WF_LMAC_RST_SEL[16]      - (RW) LMAC band0 reset selection
                                     1'b0: bn0_wf_lmac_rst_b
                                     1'b1: bn1_wf_lmac_rst_b | bn0_wf_lmac_rst_b
    BN1_WF_LMAC_RST_SEL[17]      - (RW) LMAC band1 reset selection
                                     1'b0: bn1_wf_lmac_rst_b
                                     1'b1: bn1_wf_lmac_rst_b | bn0_wf_lmac_rst_b
    RESERVED18[31..18]           - (RO) Reserved bits

 =====================================================================================*/
