/* =====================================================================================

  ---WF_UMAC_PWR_CTL (0x81020000 + 0x50)---

    UMAC_SOFT_RSTB[0]            - (RW) when UMAC mtcmos control flow selection = 0, UMAC power domian reset manual control
                                     0: reset UMAC power domian
                                     1: not reset UMAC power domian
    UMAC_SOFT_ISO_EN[1]          - (RW) when UMAC mtcmos control flow selection = 0, UMAC power domain isolation manual control
                                     0: not isolating UMAC power domain output signals
                                     1: isolating UMAC power domain output signals
    UMAC_SOFT_PWR_ON_S[2]        - (RW) when UMAC mtcmos control flow selection = 0, UMAC mtcmos secondary power switch manual control
                                     0: power off UMAC mtcmos
                                     1: power on UMAC mtcmos
    UMAC_SOFT_PWR_ON[3]          - (RW) when UMAC mtcmos control flow selection = 0, UMAC mtcmos primary power switch manual control
                                     0: power off UMAC mtcmos
                                     1: power on UMAC mtcmos
    UMAC_HWCTL[4]                - (RW) UMAC mtcmos control flow selection
                                     0: SW flow (by CR)
                                     1: H/W flow (by mtcmos FSM)
    UMAC_PWR_CHECK_WITH_MEM_PWR_EN[5] - (RW) check UMAC memory is power-off before umac mtcmos is power-off
                                     0: disable
                                     1: enable
    UMAC_PWR_ON_SELECT[6]        - (RW) UMAC mtcmos FSM trigger selection
                                     0: S/W trigger (by CR)
                                     1: H/W trigger (H/W signal is same as TOP H/W trigger signal) 
                                     (this CR must be set to 1 when UMAC's power is control by TOP power)
    UMAC_PWR_ON[7]               - (RW) when UMAC mtcmos FSM trigger selection = 0
                                     0: trigger FSM to power off UMAC mtcmos
                                     1: trigger FSM to power on UMAC mtcmos
    UMAC_DSLEEP_HWCTL[8]         - (RW) enable UMAC with dsleep mode
    RESERVED9[31..9]             - (RO) Reserved bits

 =====================================================================================*/
